        case 20: return c_EccentricitySeriesTable{2, 20, c_eccentricity_modes_l2_e20, c_eccentricity_coeffs_l2_e20};
        case 50: return c_EccentricitySeriesTable{2, 50, c_eccentricity_modes_l2_e50, c_eccentricity_coeffs_l2_e50};
        default: return c_EccentricitySeriesTable{};
